package com.alibaba.adp.fee.core.calculator;

import com.alibaba.adp.fee.api.model.response.OrderLogisticsFeeDetail;
import com.alibaba.adp.fee.core.spi.FreightCalculator;
import com.alibaba.adp.fee.core.spi.FreightCollector;
import com.alibaba.adp.fee.core.spi.LogisticsGrouping;
import com.alibaba.adp.fee.core.spi.PackageCombiner;
import com.alibaba.adp.fee.core.spi.model.FreightGroup;
import com.alibaba.adp.fee.core.spi.model.GroupLogisticsFee;
import com.alibaba.adp.fee.core.spi.model.LogisticsPackage;
import com.google.common.collect.Lists;
import org.apache.commons.collections4.CollectionUtils;

import java.util.List;

/**
 * 运费执行器
 * @author jiajun.njj 2021/6/16 5:48 下午
 */
public class FreightExecutor {

    private List<PackageCombiner> combiners;

    private List<LogisticsGrouping> groupings;

    private List<FreightCalculator> calculators;

    private List<FreightCollector> collectors;

    /**
     * 1.包裹构建（跨主单合并）——业务定制
     * 2.按定制后包裹计算运费，这里的每个包裹运费需要进行汇总；
     * 3.构建运费计算分组 —— 按运费模版归组计算运费
     * 4.多组运费结果逐订单汇总 —— 业务定制
     */
    public List<OrderLogisticsFeeDetail> execute(List<LogisticsPackage> packages) {
        // 包裹合并
        for (PackageCombiner combiner : combiners) {
            if (!combiner.canCombine(packages)) {
                continue;
            }
            // 选出需要合并的包裹
            List<LogisticsPackage> pickedPackages = combiner.pickUpPackages(packages);
            if (CollectionUtils.isEmpty(pickedPackages)) {
                continue;
            }
            // 移除原包裹
            packages.removeAll(pickedPackages);
            // 添加合并后的包裹
            packages.addAll(combiner.combine(pickedPackages));
        }
        List<OrderLogisticsFeeDetail> orderFees = Lists.newArrayList();
        // 逐包裹计算运费
        for (LogisticsPackage logisticsPackage : packages) {
            if (CollectionUtils.isEmpty(logisticsPackage.getFreightItems())) {
                continue;
            }
            List<OrderLogisticsFeeDetail> packageFees = packageFeeCalculate(logisticsPackage);
            orderFees.addAll(packageFees);
        }
        return orderFees;
    }

    /**
     * 包裹费用计算
     * 1. 构建运费分组 —— 按运费模版归组计算运费
     * 2. 多组运费结果逐订单汇总 —— 业务定制
     */
    private List<OrderLogisticsFeeDetail> packageFeeCalculate(LogisticsPackage logisticsPackage) {
        // 构建运费分组
        List<FreightGroup> freightGroups = buildFreightGroups(logisticsPackage);
        // 按运费模版归组计算运费
        List<GroupLogisticsFee> groupLogisticsFees = groupFeeCalculate(freightGroups);

        List<OrderLogisticsFeeDetail> orderFees = Lists.newArrayList();
        // 多组运费结果汇总
        for (FreightCollector collector : collectors) {
            if (CollectionUtils.isEmpty(groupLogisticsFees)) {
                break;
            }
            // 运费汇总到订单
            List<OrderLogisticsFeeDetail> collectedFee = collector.collect(logisticsPackage, groupLogisticsFees);
            if (CollectionUtils.isEmpty(collectedFee)) {
                continue;
            }
            orderFees.addAll(collectedFee);
            break;
        }
        return orderFees;
    }

    private List<GroupLogisticsFee> groupFeeCalculate(List<FreightGroup> freightGroups) {
        List<GroupLogisticsFee> groupLogisticsFees = Lists.newArrayList();
        // 逐分组计算运费
        for (FreightGroup freightGroup : freightGroups) {
            for (FreightCalculator calculator : calculators) {
                if (!calculator.canCalculate(freightGroup)) {
                    continue;
                }
                GroupLogisticsFee groupFee = calculator.calculate(freightGroup);
                if (groupFee != null) {
                    groupLogisticsFees.add(groupFee);
                    break;
                }
            }
        }
        return groupLogisticsFees;
    }

    private List<FreightGroup> buildFreightGroups(LogisticsPackage logisticsPackage) {
        List<FreightGroup> freightGroups = Lists.newArrayList();
        for (LogisticsGrouping grouping : groupings) {
            // 允许业务定制运费计算分组规则
            List<FreightGroup> groups = grouping.grouping(logisticsPackage);
            if (CollectionUtils.isNotEmpty(groups)) {
                freightGroups.addAll(groups);
                break;
            }
        }
        return freightGroups;
    }

    public void setCombiners(List<PackageCombiner> combiners) {
        this.combiners = combiners;
    }

    public void setGroupings(List<LogisticsGrouping> groupings) {
        this.groupings = groupings;
    }

    public void setCalculators(List<FreightCalculator> calculators) {
        this.calculators = calculators;
    }

    public void setCollectors(List<FreightCollector> collectors) {
        this.collectors = collectors;
    }
}

