/**
 * .
 *
 * @author ī�� lee.jl@alibaba-inc.com
 * @version 1.0
 * @since 2023/09/21
 */
public class FeeCalculateV2Ability extends CombineAbility {

    private final Logger logger = LoggerFactory.getLogger(this.getClass());

    private static final int FEE_CALCULATE_V2_GRAY_MODE_ONLY_V1 = 0;

    private static final int FEE_CALCULATE_V2_GRAY_MODE_COMPARE_AND_V1 = 1;

    private static final int FEE_CALCULATE_V2_GRAY_MODE_COMPARE_AND_V2 = 2;

    private static final int FEE_CALCULATE_V2_GRAY_MODE_ONLY_V2 = 3;

    @Resource
    private AdpFeeCalculateService adpFeeCalculateService;

    @Resource
    private ReplaceTemplateFeeCalculator replaceTemplateFeeCalculator;

    @Resource
    private MockedFeeCalculator mockedFeeCalculator;

    @Resource
    private DirectAdditionFeeCalculator directAdditionFeeCalculator;

    @Resource
    private SellerDirectGlobalFeeCalculator sellerDirectGlobalFeeCalculator;

    @Resource
    private DirectFeeCalculator directFeeCalculator;

    @Resource
    private PartnerFeeCalculator partnerFeeCalculator;

    @MonitorPerformRecorder(
            name = AdpBizAbilityConstant.ADP_L1_FEE_CALCULATE_V2_ABILITY,
            externalConfigNamespace = AdpBizAbilityConstant.ADP_PLATFORM_METRIC_CONFIG_NAMESPACE,
            externalConfigKey = AdpBizAbilityConstant.ADP_L1_FEE_CALCULATE_V2_ABILITY_METRIC_CONFIG_KEY
    )
    @MonitorPerformProfiler(
            name = AdpBizAbilityConstant.ADP_L1_ABILITY_PROFILE,
            externalConfigNamespace = AdpBizAbilityConstant.ADP_PLATFORM_METRIC_CONFIG_NAMESPACE,
            externalConfigKey = AdpBizAbilityConstant.ADP_L1_ABILITY_PROFILE_CONFIG_KEY
    )
    @Override
    public AdpResult<Boolean> fill(DeliveryPackageGroupDO groupDO, AdpOption adpOption) {

        try {

            Long sellerId = Optional.ofNullable(groupDO.getDeliveryPackageGroupDTO())
                .map(DeliveryPackageGroupDTO::getPackageList)
                .orElseGet(Collections::emptyList)
                .stream()
                .map(DeliveryPackageDTO::getSellerInfo)
                .filter(Objects::nonNull)
                .map(SellerInfoDTO::getSellerId)
                .filter(Objects::nonNull)
                .findFirst()
                .orElse(9999L);
            Long buyerId = Optional.ofNullable(groupDO.getDeliveryPackageGroupDTO())
                .map(DeliveryPackageGroupDTO::getPackageList)
                .orElseGet(Collections::emptyList)
                .stream()
                .map(DeliveryPackageDTO::getBuyerInfo)
                .filter(Objects::nonNull)
                .map(BuyerInfoDTO::getBuyerId)
                .filter(Objects::nonNull)
                .findFirst()
                .orElse(9999L);
            int feeCalculateV2GrayMode = AdpNewLogisticBizConfig.calculateFeeV2GrayMode(sellerId, buyerId);
            if (feeCalculateV2GrayMode == FEE_CALCULATE_V2_GRAY_MODE_ONLY_V1) {
                return executeV1(groupDO, adpOption);
            }

            /*
                ��ΪFeeCalculateV2Abilityͬʱ������ packageConvergeAbility��feeCalculatorAbility��packageReSplitAbility ������ability�Ĺ��ܣ�
                ���������Ҫͬʱ����������ability��useAbility�߼�������
                    1. packageConvergeAbility��ֻ��ability�ӿں�confirm�ӿ�
                    2. feeCalculatorAbility��  option.isCalcPostFee() == true
                         a. minato���������true
                         b. detail���������true
                         c. ability�����У����˲�����Դ����Ҫ�����˷ѣ�������������֮�⣬������true
                         d. confirm�����У����˲�����Դ����Ҫ�����˷ѣ�������������֮�⣬������true
                    3. packageReSplitAbility�� ֻ��ability�ӿں�confirm�ӿ�
             */
            boolean isAllowCalcSource = AdpInterfaceSource.ABILITY.equals(adpOption.getInterfaceSource()) ||
                AdpInterfaceSource.CONFIRM.equals(adpOption.getInterfaceSource());
            boolean isFeeCalc = adpOption.isCalcPostFee();
            // �µ��˷Ѽ������̣�isAllowCalcSource �� isFeeCalc �������㼴��
            if (!(isAllowCalcSource || isFeeCalc)) {
                return executeV1(groupDO, adpOption);
            }

            Map<String, Map<Long, Set<Long>>> protocolMap = collectProtocol(groupDO);
            Set<Long> candidateProtocolIdSet = collectCandidateProtocol(protocolMap);

            // ����v2�汾�˷�
            AdpResult<PostFeeCalculateResponse> v2Result = executeV2(groupDO, adpOption, candidateProtocolIdSet);
            if (!v2Result.isSuccess() && AdpNewLogisticBizConfig.feeCalculateV2DemoteToV1IfFail) {
                return executeV1(groupDO, adpOption);
            }

            // ��ȡ����ά�ȵ��˷ѽ��
            Map<String, List<CompatiblePostFeeResult>> v2FeeResultMap = FeeCalculateAdapterUtils.adaptV2(v2Result.getModel());
            if (feeCalculateV2GrayMode == FEE_CALCULATE_V2_GRAY_MODE_ONLY_V2) {
                // ֻ����v2�汾����ֱ�ӽ�v2�����䵽������
                this.fillV2Result(groupDO, v2FeeResultMap, adpOption);
                return AdpResult.success();
            } else {
                /*
                    ����Ա����̣���������������
                        1 �Ա�֮����v1���
                        2 �Ա�֮����v2���
                 */
                if (feeCalculateV2GrayMode == FEE_CALCULATE_V2_GRAY_MODE_COMPARE_AND_V1) {
                    // ����v1���
                    AdpResult<Boolean> v1Result = executeV1(groupDO, adpOption);

                    // ��ȡ���˷���ص����������ʱv1�����飬����֮��ĶԱ�
                    DeliveryPackageGroupDO v1ProtocolGroup = extractProtocol(groupDO);
                    try {
                        // ����һ����ʱ��v2����ģ�ͣ�����ȡ���˷���ص����������ʱv2������
                        DeliveryPackageGroupDO compareGroup = feeCloneGroup(groupDO);
                        this.fillV2Result(compareGroup, v2FeeResultMap, adpOption);
                        DeliveryPackageGroupDO v2ProtocolGroup = extractProtocol(compareGroup);
                        // �Ա�������ʱ������
                        this.compareV1AndV2(v1ProtocolGroup, v2ProtocolGroup);
                    } finally {
                        recoverProtocol(groupDO, v1ProtocolGroup);
                    }

                    return v1Result;
                } else {
                    // ����ʹ��v2���������ֱ���������õ�������
                    this.fillV2Result(groupDO, v2FeeResultMap, adpOption);
                    // ��ȡ���˷���ص����������ʱv2�����飬����֮��ĶԱ�
                    DeliveryPackageGroupDO v2ProtocolGroup = extractProtocol(groupDO);
                    try {
                        // ����һ����ʱ��v1����ģ�ͣ�����ȡ���˷���ص����������ʱv1������
                        DeliveryPackageGroupDO compareGroup = feeCloneGroup(groupDO);
                        executeV1(compareGroup, adpOption);
                        DeliveryPackageGroupDO v1ProtocolGroup = extractProtocol(compareGroup);
                        // �Ա�����������
                        this.compareV1AndV2(v1ProtocolGroup, v2ProtocolGroup);
                    } finally {
                        recoverProtocol(groupDO, v2ProtocolGroup);
                    }

                    return AdpResult.success();
                }
            }
        } catch (Exception e) {
            String logStr = AdpCommonLogV2StrUtil.buildCompareLogStr(AdpInterfaceSource.FEE_V2_CAL.getInterfaceName(), "fee.calculate.v2.compare", "fillException");
            String exceptionStr = AdpCommonLogV2StrUtil.buildDifference("fee.calculate.v2.fillException", e.getMessage());
            SlsLogisticsRecordPersistentV2.LOG.save(logStr + exceptionStr);
            if (AdpNewLogisticBizConfig.feeCalculateV2DemoteToV1IfFail) {
                return executeV1(groupDO, adpOption);
            } else {
                return AdpResult.failed();
            }
        }
    }

    private AdpResult<Boolean> executeV1(DeliveryPackageGroupDO groupDO, AdpOption adpOption) {
        return super.fill(groupDO, adpOption);
    }

    private AdpResult<PostFeeCalculateResponse> executeV2(DeliveryPackageGroupDO groupDO, AdpOption adpOption,
                                                          Set<Long> candidateProtocolIdSet) {
        try {
            // ת��������Ϣ
            // Ŀǰҵ�������ǰ���ά�ȵģ�ȫ��ά���޷�Ψһ�������˷���֧����ҵ��������������
            AdpInvokeInfo adpInvokeInfo = new AdpInvokeInfo();
            adpInvokeInfo.setAppName(AdpInvokeInfo.ADP_NAME_INTERNAL);
            adpInvokeInfo.setInterfaceSource(adpOption.getInterfaceSource());

            // ԤУ���Ƿ���Ҫִ���˷Ѽ���
            String preCheck = FeeCalculateAdapterUtils.isNeedCalculatePostFee(groupDO, adpOption);
            if (!SuccessErrorEnum.SUCCESS.getCode().equals(preCheck)) {
                // ��������˷�
                String logStr = AdpCommonLogV2StrUtil.buildCompareLogStr(AdpInterfaceSource.FEE_V2_CAL.getInterfaceName(), "fee.calculate.v2.compare", "noNeedCalculate");
                SlsLogisticsRecordPersistentV2.LOG.save(logStr);
                return AdpResult.failed();
            }

            // ת���˷Ѽ����������
            PostFeeCalculateRequest request = FeeCalculateAdapterUtils.convertToV2Request(
                groupDO, adpOption, candidateProtocolIdSet);

            // ִ�м���
            return adpFeeCalculateService.calculatePostFee(request, adpInvokeInfo);
        } catch (Throwable t) {
            String logStr = AdpCommonLogV2StrUtil.buildCompareLogStr(AdpInterfaceSource.FEE_V2_CAL.getInterfaceName(), "fee.calculate.v2.compare", "executeException");
            String exceptionStr = AdpCommonLogV2StrUtil.buildDifference("fee.calculate.v2.executeException", t.getMessage());
            SlsLogisticsRecordPersistentV2.LOG.save(logStr + exceptionStr);
            return AdpResult.failed();
        }
    }

    private DeliveryPackageGroupDO extractProtocol(DeliveryPackageGroupDO deliveryPackageGroupDO) {
        DeliveryPackageGroupDO protocolGroup = new DeliveryPackageGroupDO();
        protocolGroup.setDeliveryProtocolList(deliveryPackageGroupDO.getDeliveryProtocolList());
        protocolGroup.setDeliveryPackageDOList(new ArrayList<>());
        for (DeliveryPackageDO deliveryPackageDO : deliveryPackageGroupDO.getDeliveryPackageDOList()) {
            DeliveryPackageDO protocolPackage = new DeliveryPackageDO();
            protocolPackage.setDeliveryProtocolList(deliveryPackageDO.getDeliveryProtocolList());
            protocolPackage.setUniqueId(deliveryPackageDO.getUniqueId());
            protocolPackage.setDeliveryCarrierList(new ArrayList<>());
            for (DeliveryCarrierDO deliveryCarrierDO : deliveryPackageDO.getDeliveryCarrierList()) {
                DeliveryCarrierDO protocolCarrier = new DeliveryCarrierDO();
                protocolCarrier.setDeliveryProtocolList(deliveryCarrierDO.getDeliveryProtocolList());
                protocolCarrier.setUniqueId(deliveryCarrierDO.getUniqueId());
                DeliveryCarrierDTO deliveryCarrierDTO = deliveryCarrierDO.getDeliveryCarrierDTO();
                if (deliveryCarrierDTO != null) {
                    DeliveryCarrierDTO protocolCarrierDTO = protocolCarrier.getDeliveryCarrierDTO();
                    if (protocolCarrierDTO == null) {
                        protocolCarrierDTO = new DeliveryCarrierDTO();
                        protocolCarrier.setDeliveryCarrierDTO(protocolCarrierDTO);
                    }
                    protocolCarrierDTO.setItemId(deliveryCarrierDTO.getItemId());
                    protocolCarrierDTO.setSkuId(deliveryCarrierDTO.getSkuId());
                    protocolCarrierDTO.setCategoryId(deliveryCarrierDTO.getCategoryId());
                }
                protocolPackage.getDeliveryCarrierList().add(protocolCarrier);
            }
            protocolGroup.getDeliveryPackageDOList().add(protocolPackage);
        }
        return protocolGroup;
    }

    private Map<String, Map<Long, Set<Long>>> collectProtocol(DeliveryPackageGroupDO groupDO) {
        Map<String, Map<Long, Set<Long>>> resultMap = new HashMap<>();
        for (DeliveryPackageDO deliveryPackageDO : groupDO.getDeliveryPackageDOList()) {
            if (CollectionUtils.isEmpty(deliveryPackageDO.getDeliveryProtocolList())) {
                continue;
            }
            String packageKey = deliveryPackageDO.packageKey();
            for (DeliveryProtocolDO deliveryProtocolDO : deliveryPackageDO.getDeliveryProtocolList()) {
                boolean existFictionProtocol = Optional.ofNullable(deliveryPackageDO.getDeliveryProtocolList())
                    .orElseGet(Collections::emptyList)
                    .stream()
                    .anyMatch(protocol -> protocol.getProtocolDefinitionDO().isFictitious());
                // 1. ���ݳ�ʼ��
                Long protocolId = deliveryProtocolDO.getProtocolId();

                // 3. ����������ʽ
                Long replaceProtocolId = replaceTemplateFeeCalculator.replaceProtocolId(deliveryPackageDO, protocolId);
                Set<Long> protocolIdSet;
                if (Objects.nonNull(replaceProtocolId)) {
                    protocolIdSet = allProtocolSet(replaceProtocolId);
                } else if (Adp2MigrateUtils.ifGray() && AdpProtocol.DELIVERY_SERVICETYPE_MENDIAN_JSD == protocolId) {
                    // ����ҵ���������ٴ���childServiceType�����˷�
                    if (deliveryProtocolDO.getUserChooseLogisticsInfo() == null ||
                        deliveryProtocolDO.getUserChooseLogisticsInfo().getChildServiceType() == null) {
                        throw new AdpServiceException(
                            AdpServiceErrorCode.ADP_SYSTEM_ERROR_CAN_NOT_FIND_USER_SELECT_SERVICE_TYPE,
                                AdpServiceErrorCode.ADP_SYSTEM_ERROR_CAN_NOT_FIND_USER_SELECT_SERVICE_TYPE.getMessage()
                                + protocolId,
                                "FeeCalculateV2Ability");
                    }
                    protocolId = deliveryProtocolDO.getUserChooseLogisticsInfo().getChildServiceType();
                    // ���ٴ�ֱ��add��set����
                    protocolIdSet = new HashSet<>(8);
                    protocolIdSet.add(protocolId);
                } else if (existFictionProtocol) {
                    protocolId = mockedFeeCalculator.computeMockedProtocolId(deliveryPackageDO, deliveryProtocolDO);
                    protocolIdSet = allProtocolSet(protocolId);
                } else {
                    protocolIdSet = allProtocolSet(protocolId);
                }

                if (protocolId != null) {
                    resultMap.computeIfAbsent(packageKey, k -> new HashMap<>())
                        .computeIfAbsent(protocolId, pid -> new HashSet<>())
                        .addAll(protocolIdSet);
                }
            }
        }
        return resultMap;
    }

    private Set<Long> collectCandidateProtocol(Map<String, Map<Long, Set<Long>>> protocolMap) {
        if (!AdpNewLogisticBizConfig.isFeeCalculateV2EnableLogisTypeFilter()) {
            return null;
        }
        Set<Long> candidateProtocolIdSet = Optional.of(protocolMap.values())
            .orElseGet(Collections::emptyList)
            .stream()
            .map(Map::values)
            .flatMap(Collection::stream)
            .filter(Objects::nonNull)
            .flatMap(Set::stream)
            .filter(Objects::nonNull)
            .collect(Collectors.toSet());
        if (candidateProtocolIdSet.isEmpty()) {
            candidateProtocolIdSet = null;
        }
        return candidateProtocolIdSet;
    }

