    /**
     * ��¡����Э��
     * @param deliveryProtocolDO ԴЭ��
     * @return ��Э��
     */
    private DeliveryProtocolDO feeProtocolClone(DeliveryProtocolDO deliveryProtocolDO) {

        DeliveryProtocolDO shadowCloneProtocol = new DeliveryProtocolDO();
        BeanUtils.copyProperties(deliveryProtocolDO, shadowCloneProtocol);

        // �˷�����
        shadowCloneProtocol.setFeeDO(new FeeDO());
        shadowCloneProtocol.setPostFeeSnapshot(new ArrayList<>());

        // ��Ϊ���ʶε��˷ѣ���sdp����ģ���Щ����v2��������˷ѣ���������ⲿ�ֳ������������ã�Ҫ���¸�ֵԭ���Ľ��
        boolean isNeedReserve = this.isNeedReserveSourceData(deliveryProtocolDO);
        if (isNeedReserve) {
            ProtocolDefinitionDO sourceDefinition = deliveryProtocolDO.getProtocolDefinitionDO();
            FeeDO sourceFee = deliveryProtocolDO.getFeeDO();
            if (sourceFee != null && sourceDefinition != null) {
                shadowCloneProtocol.setFeeDO(deliveryProtocolDO.getFeeDO());
                if (CollectionUtils.isNotEmpty(deliveryProtocolDO.getPostFeeSnapshot())) {
                    shadowCloneProtocol.setPostFeeSnapshot(deliveryProtocolDO.getPostFeeSnapshot());
                }
            }
        }

        // ������ѡ�������
        boolean existBuyerSelectPartner = Optional.ofNullable(shadowCloneProtocol.getProtocolDefinitionDO())
            .map(ProtocolDefinitionDO::getServiceOptions)
            .map(ProtocolOptionsDO::getBuyerSelectFastOptionDOList)
            .map(CollectionUtils::isNotEmpty)
            .orElse(false);
        if (existBuyerSelectPartner) {
            ProtocolDefinitionDO shadowCloneDefinition = new ProtocolDefinitionDO();
            BeanUtils.copyProperties(shadowCloneProtocol.getProtocolDefinitionDO(), shadowCloneDefinition);
            shadowCloneProtocol.setProtocolDefinitionDO(shadowCloneDefinition);

            ProtocolOptionsDO protocolOptionsDO = new ProtocolOptionsDO();
            BeanUtils.copyProperties(shadowCloneDefinition.getServiceOptions(), protocolOptionsDO);
            shadowCloneDefinition.setServiceOptions(protocolOptionsDO);

            protocolOptionsDO.setBuyerSelectFastOptionDOList(
                protocolOptionsDO.getBuyerSelectFastOptionDOList().stream()
                    .map(SerializationUtils::clone)
                    .collect(Collectors.toList()));
        }

        return shadowCloneProtocol;
    }

    private void recoverProtocol(DeliveryPackageGroupDO group, DeliveryPackageGroupDO protocolGroup) {
        group.setDeliveryProtocolList(protocolGroup.getDeliveryProtocolList());
        Map<Integer, DeliveryPackageDO> protocolPackageMapByUniqueId
            = protocolGroup.getDeliveryPackageDOList().stream()
            .collect(Collectors.toMap(DeliveryPackageDO::getUniqueId, Function.identity()));
        for (DeliveryPackageDO deliveryPackageDO : group.getDeliveryPackageDOList()) {
            DeliveryPackageDO protocolPackage = protocolPackageMapByUniqueId.get(deliveryPackageDO.getUniqueId());
            deliveryPackageDO.setDeliveryProtocolList(protocolPackage.getDeliveryProtocolList());
            Map<Integer, DeliveryCarrierDO> protocolCarrierByUniqueId
                = protocolPackage.getDeliveryCarrierList().stream()
                .collect(Collectors.toMap(DeliveryCarrierDO::getUniqueId, Function.identity()));
            for (DeliveryCarrierDO deliveryCarrierDO : deliveryPackageDO.getDeliveryCarrierList()) {
                DeliveryCarrierDO protocolCarrier = protocolCarrierByUniqueId.get(deliveryCarrierDO.getUniqueId());
                deliveryCarrierDO.setDeliveryProtocolList(protocolCarrier.getDeliveryProtocolList());
            }
        }
    }

    private void compareV1AndV2(DeliveryPackageGroupDO v1Result, DeliveryPackageGroupDO v2Result) {
        Map<String, List<CompatiblePostFeeResult>> v1FeeResultMap = FeeCalculateAdapterUtils.adaptV1(v1Result);
        Map<String, List<CompatiblePostFeeResult>> v2FeeResultMap = FeeCalculateAdapterUtils.adaptV1(v2Result);
        String difference = AdpDiffUtils.diff(v1FeeResultMap, v2FeeResultMap);
        if (StringUtils.isNotEmpty(difference)) {
            String logStr = AdpCommonLogV2StrUtil.buildCompareLogStr(AdpInterfaceSource.FEE_V2_CAL.getInterfaceName(), "fee.calculate.v2.compare", "difference");
            String differenceStr = AdpCommonLogV2StrUtil.buildDifference("fee.calculate.v2.difference", difference);
            String finalStr = logStr + differenceStr;
            SlsLogisticsRecordPersistentV2.LOG.save(finalStr);
        } else {
            String logStr = AdpCommonLogV2StrUtil.buildCompareLogStr(AdpInterfaceSource.FEE_V2_CAL.getInterfaceName(), "fee.calculate.v2.compare", "passed");
            SlsLogisticsRecordPersistentV2.LOG.save(logStr);
        }
    }

    private void fillV2Result(DeliveryPackageGroupDO groupDO,
                              Map<String, List<CompatiblePostFeeResult>> v2FeeResultMap,
                              AdpOption adpOption) {

        // �˷ѽ������
        for (DeliveryPackageDO deliveryPackageDO : groupDO.getDeliveryPackageDOList()) {
            if (CollectionUtils.isEmpty(deliveryPackageDO.getDeliveryProtocolList())) {
                // ����ЧЭ�飬�޷������˷�
                continue;
            }
            String packageKey = deliveryPackageDO.packageKey();
            // ��ȡ��ǰ������Ӧ���˷��б�
            List<CompatiblePostFeeResult> v2PkgResultList = v2FeeResultMap.get(packageKey);
            if (CollectionUtils.isEmpty(v2PkgResultList)) {
                // δ������˷ѷ���
                continue;
            }
            for (DeliveryProtocolDO deliveryProtocolDO : deliveryPackageDO.getDeliveryProtocolList()) {

                // 1. ����ҵ������ADP�˷�ģ������˷�
                long protocolId = deliveryProtocolDO.getProtocolId();

                // 1.1 ����ҵ�����⴦�������⼯�˼�����ֱ�ͣ��������ADP�˷�ģ������˷�
                boolean isNeedReserve = this.isNeedReserveSourceData(deliveryProtocolDO);
                if (isNeedReserve) {
                    continue;
                }

                // 1.2 taobaoСʱ��2.0����ADP�˷�ģ��
                if (AdpProtocol.isTbXsdHourReach(protocolId)) {
                    continue;
                }

                boolean existFictionProtocol = Optional.ofNullable(deliveryPackageDO.getDeliveryProtocolList())
                    .orElseGet(Collections::emptyList)
                    .stream()
                    .anyMatch(protocol -> protocol.getProtocolDefinitionDO().isFictitious());

                // 2. ѡ�����ŵ��˷�
                CompatiblePostFeeResult selectedV2Result = this.selectFeeResult(deliveryPackageDO, deliveryProtocolDO, v2PkgResultList, existFictionProtocol);
                if (Objects.isNull(selectedV2Result)) {
                    // �����˷�ʧ��
                    throw new AdpServiceException(AdpServiceErrorCode.ADP_BIZ_ERROR_FEE_UN_EXECUTABLE,
                            AdpServiceErrorCode.ADP_BIZ_ERROR_FEE_UN_EXECUTABLE.getMessage()
                                    + "#" + deliveryPackageDO.getOutId()
                                    + "," + deliveryProtocolDO.getProtocolId(),
                            "FeeCalculateV2Ability");
                }

                // 3. ��ֵ��Э���˷�ģ����
                FeeDO feeDO = deliveryProtocolDO.getFeeDO();
                feeDO.setPrice(selectedV2Result.getPostFee());
                feeDO.setPriceUnit(selectedV2Result.getPostFeeUnit());
                feeDO.setMinatoInfoDO(selectedV2Result.getMinatoInfo());
                feeDO.setFeeCalcPackageInfoDO(selectedV2Result.getFeeCalcPackageInfoDO());
                Optional.of(selectedV2Result)
                    .map(CompatiblePostFeeResult::getFeeSnapshot)
                    .map(PostFeeSnapshotDO::getCalFeeMethod)
                    .ifPresent(feeDO::setCalFeeMethod);
                Optional.of(selectedV2Result)
                    .map(CompatiblePostFeeResult::getFeeSnapshot)
                    .map(PostFeeSnapshotDO::getCalFeeVer)
                    .ifPresent(feeDO::setCalFeeVer);
                Optional.ofNullable(selectedV2Result.getFeeSnapshot())
                    .ifPresent(postFeeSnapshotDO -> {
                        postFeeSnapshotDO.setProtocolId(deliveryProtocolDO.getProtocolId());
                        if (selectedV2Result.isProtocolReplaced()) {
                            postFeeSnapshotDO.setReplaceProtocolId(selectedV2Result.getProtocolId());
                            // �����Э���滻����snapshot�е�type��Ϊreplace
                            postFeeSnapshotDO.setCalculator("replace");
                        } else {
                            postFeeSnapshotDO.setReplaceProtocolId(null);
                        }
                        if (existFictionProtocol) {
                            postFeeSnapshotDO.setCalculator(FeeCalculateAdapterUtils.FEE_CALCULATOR_MULTI_LOGIS_TYPE);
                        }
                    });
                deliveryProtocolDO.setPostFeeSnapshot(Lists.newArrayList(selectedV2Result.getFeeSnapshot()));

                // ����ҵ��������������̯����£���չʾ������ѡ���
                if (selectedV2Result.isFromApportion()
                    && PackageConvergeUtils.isNotSupportChooseExpress(deliveryPackageDO)) {
                    Optional.ofNullable(deliveryProtocolDO.getProtocolDefinitionDO())
                        .map(ProtocolDefinitionDO::getServiceOptions)
                        .map(ProtocolOptionsDO::getBuyerSelectFastOptionDOList)
                        .filter(CollectionUtils::isNotEmpty)
                        .ifPresent(List::clear);
                }
            }
        }

        // ����ҵ���������⼯��
        this.overseaConsoHandle(groupDO, adpOption);

        // ����ҵ��������������ֱ��
        this.overseaSellerDirectHandle(groupDO, adpOption);

        // ����ҵ������Сʱ��
        this.hourReachSpecialHandle(groupDO, adpOption);

        // ����ҵ������������ѡ���
        this.partnerFeeCalculatorHandle(groupDO, adpOption);

        // ������ʾ���ù��˴���
        this.postFeeFreeHintHandle(groupDO, adpOption);
    }

    /**
     * �Ƿ���Ҫ����Դ����
     * @return
     */
    private boolean isNeedReserveSourceData(DeliveryProtocolDO deliveryProtocolDO) {
        long protocolId = deliveryProtocolDO.getProtocolId();
        // ���⼯��
        boolean overseaConso = AdpProtocol.isConsoDirect(protocolId);
        // ����ֱ��
        boolean overseaSellerDirect = DeliveryFeeCalculateExecutor.skipPostFeeProtocols.contains(protocolId);
        // ����η���
        boolean overseaDirect = directFeeCalculator.filter(null, deliveryProtocolDO, null);

        return overseaConso || overseaSellerDirect || overseaDirect;
    }

    /**
     * ���ݰ���Э�飬ѡ�����ŵ��˷�
     * @param deliveryPackageDO
     * @param deliveryProtocolDO
     * @param v2PkgResultList
     * @param existFictionProtocol
     * @return �˷ѽ��
     */
    private CompatiblePostFeeResult selectFeeResult(DeliveryPackageDO deliveryPackageDO,
                                                    DeliveryProtocolDO deliveryProtocolDO,
                                                    List<CompatiblePostFeeResult> v2PkgResultList,
                                                    boolean existFictionProtocol) {

        // 1. ���ݳ�ʼ��
        Long protocolId = deliveryProtocolDO.getProtocolId();

        // 2. ����������ʽ
        Long replaceProtocolId = replaceTemplateFeeCalculator.replaceProtocolId(deliveryPackageDO, protocolId);
        Set<Long> protocolIdSet;
        if (Objects.nonNull(replaceProtocolId)) {
            protocolIdSet = allProtocolSet(replaceProtocolId);
        } else if (Adp2MigrateUtils.ifGray() && AdpProtocol.DELIVERY_SERVICETYPE_MENDIAN_JSD == protocolId) {
            // ����ҵ���������ٴ���childServiceType�����˷�
            if (deliveryProtocolDO.getUserChooseLogisticsInfo() == null ||
                deliveryProtocolDO.getUserChooseLogisticsInfo().getChildServiceType() == null) {
                throw new AdpServiceException(
                    AdpServiceErrorCode.ADP_SYSTEM_ERROR_CAN_NOT_FIND_USER_SELECT_SERVICE_TYPE,
                        AdpServiceErrorCode.ADP_SYSTEM_ERROR_CAN_NOT_FIND_USER_SELECT_SERVICE_TYPE.getMessage() + protocolId,
                        "FeeCalculateV2Ability");
            }
            protocolId = deliveryProtocolDO.getUserChooseLogisticsInfo().getChildServiceType();
            // ���ٴ�ֱ��add��set����
            protocolIdSet = new HashSet<>(8);
            protocolIdSet.add(protocolId);
        } else if (existFictionProtocol) {
            protocolId = mockedFeeCalculator.computeMockedProtocolId(deliveryPackageDO, deliveryProtocolDO);
            protocolIdSet = allProtocolSet(protocolId);
        } else {
            protocolIdSet = allProtocolSet(protocolId);
        }

        // 3. ƥ���˷ѷ���
        CompatiblePostFeeResult selectedFeeResult = null;
        CompatiblePostFeeResult recommendFeeResult = null;
        // 3.1 ֱ��ƥ��һ���Ƿ���������˷ѷ���
        CompatiblePostFeeResult matchFeeResult = this.matchTargetFeeResult(protocolIdSet, v2PkgResultList, existFictionProtocol);
        if (Objects.nonNull(matchFeeResult)) {
            // ���ƥ���������ֵ��selectedFeeResult
            selectedFeeResult = matchFeeResult;
        }
        // 3.2 ���selectedFeeResultΪ�գ���˵��ֱ��ƥ��û�н�������Ի�ȡ�Ƽ��ķ���
        if (Objects.isNull(selectedFeeResult)) {
            // ���ƥ���������ֵ��recommendFeeResult
            recommendFeeResult = this.findRecommendFeeResult(v2PkgResultList);
        }

        // 4. �������ս��
        if (Objects.isNull(selectedFeeResult)) {
            selectedFeeResult = recommendFeeResult;
        }
        if (Objects.isNull(selectedFeeResult)) {
            List<Long> protocolIdList = new ArrayList<>(v2PkgResultList.size());
            for (CompatiblePostFeeResult compatiblePostFeeResult : v2PkgResultList) {
                protocolIdList.add(compatiblePostFeeResult.getProtocolId());
            }
            String protocolIds = StringUtils.join(protocolIdList, ",");
            logger.error("missed. protocolId:{}, calculateProtocolIds:{}", protocolId, protocolIds);
        }
        if (Objects.nonNull(selectedFeeResult)) {
            selectedFeeResult.setProtocolReplaced(Objects.nonNull(replaceProtocolId));
        }
        return selectedFeeResult;
    }

    /**
     * ƥ�����ͷ�ʽ������˷ѽ��
     * @param protocolIdSet
     * @param v2PkgResultList
     * @return �״�ƥ��Ľ��
     */
    private CompatiblePostFeeResult matchTargetFeeResult(Set<Long> protocolIdSet, List<CompatiblePostFeeResult> v2PkgResultList,
                                                        boolean existFictionProtocol) {
        if (CollectionUtils.isEmpty(protocolIdSet) || CollectionUtils.isEmpty(v2PkgResultList)) {
            return null;
        }
        for (CompatiblePostFeeResult feeResult : v2PkgResultList) {
            Long resultProtocolId = feeResult.getProtocolId();
            // 1. ���Ȼ���������ʽƥ���˷ѷ���
            if (protocolIdSet.contains(resultProtocolId)) {
                return feeResult;
            }
            // 2 ����Э�����
            if (existFictionProtocol &&
                AdpFeeLogisType.VIRTUAL_LOGIS_TYPE_MULTI.equals(resultProtocolId)) {
                return feeResult;
            }
        }
        return null;
    }

    /**
     * ��ȡ�Ƽ����˷�
     * @param v2PkgResultList
     * @return ��һ���Ƽ����˷�
     */
    private CompatiblePostFeeResult findRecommendFeeResult(List<CompatiblePostFeeResult> v2PkgResultList) {
        for (CompatiblePostFeeResult compatiblePostFeeResult : v2PkgResultList) {
            Long resultProtocolId = compatiblePostFeeResult.getProtocolId();
            // 2.3 Ĭ�϶���ʹ���Ƽ��˷ѷ������Ƽ��˷ѷ��������ж�������ﷵ�ص�һ���Ƽ����˷ѷ���
            if (compatiblePostFeeResult.isRecommend()
                && !AdpFeeLogisType.VIRTUAL_LOGIS_TYPE_MULTI.equals(resultProtocolId)) {
                if (AdpNewLogisticBizConfig.feeCalculateV2EnableDefaultSelection
                    || compatiblePostFeeResult.isFromApportion()) {
                    CompatiblePostFeeResult recommendFeeResult = this.copyNewResultToRecommend(compatiblePostFeeResult);
                    if (recommendFeeResult != null) {
                        return recommendFeeResult;
                    }
                }
            }
        }
        return null;
    }

