                            protocolId == AdpProtocol.DELIVERY_SERVICETYPE_EMS) {
                            minatoInfo.setStatusHint(AdpConstant.NOT_SHOW_IS_CAN_SELLER_PAY);
                            minatoInfo.setInfoHint(null);
                            minatoInfo.setPriceHint(null);
                            minatoInfo.setSellPayRegionPriceHint(null);
                        }
                    });
            Optional.ofNullable(deliveryPackageDO.getDeliveryProtocolList())
                .orElseGet(Collections::emptyList)
                .forEach(minatoInfoClearHandler);
            Optional.ofNullable(deliveryPackageDO.getDeliveryCarrierList())
                .orElseGet(Collections::emptyList)
                .stream().map(DeliveryCarrierDO::getDeliveryProtocolList)
                .filter(Objects::nonNull)
