    private Set<Long> allProtocolSet(Long protocolId) {
        Set<Long> protocolIdSet = new HashSet<>();
        while (null != protocolId) {
            RuleProtocolDO protocol = ProtocolRuleCache.getInstance().getProtocolById(protocolId);
            if (Objects.isNull(protocol)) {
                break;
            }
            protocolIdSet.add(protocolId);
            protocolId = protocol.getParentProtocolId();
        }
        return protocolIdSet;
    }

